CRef RefAddOption(BASIC* pbasic, int optid, CRef* prefValue)
{
    EnsureBasicSidebag(pbasic);
    return pbasic->psidebag->RefAddBinding(optid, prefValue);
}

CRef RefEnsureOption(BASIC* pbasic, int optid, CRef* prefValue)
{
    EnsureBasicSidebag(pbasic);

    if (!pbasic->psidebag->FFindBinding(optid, nullptr))
        return pbasic->psidebag->RefAddBinding(optid, prefValue);

    return pbasic->psidebag->RefSetBinding(optid, prefValue);
}

CRef RefGetOption(BASIC* pbasic, int optid)
{
    CRef ret;

    if (pbasic == nullptr || pbasic->pvtbasic == nullptr)
    {
        ret.SetTag(TAGK_None);
        return ret;
    }

    if (optid < 1173)
    {
        EOPID* peopid = PeopidFind(pbasic, optid);

        if (peopid != nullptr)
            return RefGetPeopid(pbasic, peopid);

        std::printf("RefGetOption: option not found cid=%d optid=%d object=%p\n", static_cast<int>(pbasic->pvtbasic->cid), optid, static_cast<void*>(pbasic));
    }

    if (pbasic->psidebag != nullptr && pbasic->psidebag->FFindBinding(optid, &ret))
    {
        return ret;
    }

    ret.SetTag(TAGK_None);
    return ret;
}
CRef RefSetOption(BASIC* pbasic, int optid, CRef* prefValue)
{
    CRef ret;

    if (pbasic == nullptr)
    {
        std::printf(
            "RefSetOption ERROR: pbasic=null optid=%d prefValue=%p\n",
            optid,
            static_cast<void*>(prefValue));

        ret.SetTag(TAGK_Err);
        return ret;
    }

    if (pbasic->pvtbasic == nullptr)
    {
        std::printf(
            "RefSetOption ERROR: pvtbasic=null pbasic=%p optid=%d prefValue=%p\n",
            static_cast<void*>(pbasic),
            optid,
            static_cast<void*>(prefValue));

        ret.SetTag(TAGK_Err);
        return ret;
    }

    if (optid < 1173)
    {
        EOPID* peopid = PeopidFind(pbasic, optid);

        if (peopid == nullptr)
        {
            std::printf(
                "RefSetOption ERROR: option not found pbasic=%p pvtbasic=%p cid=%d optid=%d\n",
                static_cast<void*>(pbasic),
                static_cast<void*>(pbasic->pvtbasic),
                static_cast<int>(pbasic->pvtbasic->cid),
                optid);

            ret.SetTag(TAGK_Err);
            return ret;
        }

		return RefSetPeopid(pbasic, peopid, prefValue);
    }

    EnsureBasicSidebag(pbasic);

    if (pbasic->psidebag == nullptr)
    {
        std::printf(
            "RefSetOption ERROR: sidebag allocation failed pbasic=%p optid=%d\n",
            static_cast<void*>(pbasic),
            optid);

        ret.SetTag(TAGK_Err);
        return ret;
    }

    return pbasic->psidebag->RefSetBinding(optid, prefValue);
}

CRef RefGetPeopid(BASIC* pbasic, EOPID* peopid)
{
    CRef ref;

    const OTYP otyp = static_cast<OTYP>(peopid->otyp);
    const uint32_t otypRaw = static_cast<uint32_t>(peopid->otyp);
    const GRFEOPID grfeopid = peopid->grfeopid;

    if ((grfeopid & 0x1) != 0)
    {
        auto pmethod = std::make_shared<CMethod>();
        pmethod->m_pbasic = pbasic;
        pmethod->m_pfnthunk = reinterpret_cast<PFNTHUNK>(peopid->optdat.pvThunkFn);
        pmethod->m_crefReq = static_cast<int>(peopid->optdat.crefReq);
        ref.SetMethod(pmethod);
        return ref;
    }

    BASIC* pbasicGet = pbasic;

    if ((grfeopid & 0x1000) != 0)
        pbasicGet = static_cast<BASIC*>(peopid->optdat.pfnensure(pbasic, ENSK_Get));

    if ((grfeopid & 0x2) != 0)
    {
        std::byte* pbField = reinterpret_cast<std::byte*>(pbasicGet) + peopid->optdat.ibGet;

        switch (otyp)
        {
        case OTYP_Bool:
            ref.SetBool(*reinterpret_cast<BOOL*>(pbField));
            break;

        case OTYP_Float:
            ref.SetF32(*reinterpret_cast<float*>(pbField));
            break;

        case OTYP_Vector:
            ref.SetVector(*reinterpret_cast<glm::vec3*>(pbField));
            break;

        case OTYP_Vector4:
            ref.SetVector4(*reinterpret_cast<glm::vec4*>(pbField));
            break;

        case OTYP_Matrix:
            ref.SetMatrix(glm::mat4(*reinterpret_cast<glm::mat3*>(pbField)));
            break;

        case OTYP_Int:
        case OTYP_Oid:
        case OTYP_Cid:
        case OTYP_Ishd:
        case OTYP_Sfxid:
        case OTYP_Wid:
        case OTYP_Tbid:
        case OTYP_Msgid:
        case OTYP_Musid:
        case OTYP_Optid:
            ref.SetS32(*reinterpret_cast<int32_t*>(pbField));
            break;

        case OTYP_Clq:
            ref.SetClq(*reinterpret_cast<CLQ*>(pbField));
            break;

        case OTYP_Lm:
            ref.SetLm(*reinterpret_cast<LM*>(pbField));
            break;

        case OTYP_Smp:
            ref.SetSmp(*reinterpret_cast<SMP*>(pbField));
            break;

        case OTYP_Smpa:
        case OTYP_Rgba:
        case OTYP_Void:
            break;

        default:
            if ((otypRaw & 0x1000U) != 0)
                ref.SetS32(*reinterpret_cast<int32_t*>(pbField));
            else if ((otypRaw & 0x2000U) != 0)
                ref.SetBasic(*reinterpret_cast<BASIC**>(pbField));

            break;
        }

        return ref;
    }

    PFNRAW pfnget;

    if ((grfeopid & 0x4) != 0)
    {
        pfnget = peopid->optdat.pfnget;
    }
    else
    {
        std::byte* pvt = *reinterpret_cast<std::byte**>(pbasicGet);
        pfnget = *reinterpret_cast<PFNRAW*>(pvt + peopid->optdat.ibGet);
    }

    if ((otypRaw & 0x80000000U) != 0)
        return RefGetObjectList(pbasicGet, static_cast<OTYP>(otypRaw & 0x7fffffffU), reinterpret_cast<PFNGETOBJECTLIST>(pfnget));

    switch (otyp)
    {
    case OTYP_Bool:
    {
        BOOL value = 0;
        reinterpret_cast<void(*)(void*, BOOL*)>(pfnget)(pbasicGet, &value);
        ref.SetBool(value);
        break;
    }

    case OTYP_Float:
    {
        float value = 0.0f;
        reinterpret_cast<void(*)(void*, float*)>(pfnget)(pbasicGet, &value);
        ref.SetF32(value);
        break;
    }

    case OTYP_Vector:
    {
        glm::vec3 value{};
        reinterpret_cast<void(*)(void*, glm::vec3*)>(pfnget)(pbasicGet, &value);
        ref.SetVector(value);
        break;
    }

    case OTYP_Vector4:
    {
        glm::vec4 value{};
        reinterpret_cast<void(*)(void*, glm::vec4*)>(pfnget)(pbasicGet, &value);
        ref.SetVector4(value);
        break;
    }

    case OTYP_Matrix:
    {
        glm::mat3 value(1.0f);
        reinterpret_cast<void(*)(void*, glm::mat3*)>(pfnget)(pbasicGet, &value);
        ref.SetMatrix(glm::mat4(value));
        break;
    }

    case OTYP_Int:
    case OTYP_Oid:
    case OTYP_Cid:
    case OTYP_Ishd:
    case OTYP_Sfxid:
    case OTYP_Wid:
    case OTYP_Tbid:
    case OTYP_Msgid:
    case OTYP_Musid:
    case OTYP_Optid:
    {
        int32_t value = 0;
        reinterpret_cast<void(*)(void*, int32_t*)>(pfnget)(pbasicGet, &value);
        ref.SetS32(value);
        break;
    }

    case OTYP_Clq:
    {
        CLQ value{};
        reinterpret_cast<void(*)(void*, CLQ*)>(pfnget)(pbasicGet, &value);
        ref.SetClq(value);
        break;
    }

    case OTYP_Lm:
    {
        LM value{};
        reinterpret_cast<void(*)(void*, LM*)>(pfnget)(pbasicGet, &value);
        ref.SetLm(value);
        break;
    }

    case OTYP_Smp:
    {
        SMP value{};
        reinterpret_cast<void(*)(void*, SMP*)>(pfnget)(pbasicGet, &value);
        ref.SetSmp(value);
        break;
    }

    case OTYP_Smpa:
    case OTYP_Rgba:
    case OTYP_Void:
        break;

    default:
    {
        if ((otypRaw & 0x1000U) != 0)
        {
            int32_t value = 0;
            reinterpret_cast<void(*)(void*, int32_t*)>(pfnget)(pbasicGet, &value);
            ref.SetS32(value);
        }
        else if ((otypRaw & 0x2000U) != 0)
        {
            BASIC* value = nullptr;
            reinterpret_cast<void(*)(void*, BASIC**)>(pfnget)(pbasicGet, &value);
            ref.SetBasic(value);
        }

        break;
    }
    }

    return ref;
}

CRef RefGetObjectList(BASIC* pbasic, OTYP otyp, PFNGETOBJECTLIST pfnget)
{
    CRef ref;

    GLS gls;
    gls.otyp = static_cast<OTYP>(static_cast<uint32_t>(otyp) & 0x7fffffff);

    if (pfnget)
        pfnget(pbasic, &gls);

    if (gls.ppairHead)
        ref.SetPair(gls.ppairHead);
    else
        ref.SetTag(TAGK_None);

    return ref;
}

CRef RefSetPeopid(BASIC* pbasic, EOPID* peopid, CRef* prefValue)
{
    CRef ref;
    ref.SetTag(TAGK_Void);

    const OTYP otyp = static_cast<OTYP>(peopid->otyp);
    const uint32_t otypRaw = static_cast<uint32_t>(peopid->otyp);
    const GRFEOPID grfeopid = peopid->grfeopid;

    BASIC* pbasicSet = pbasic;

    if ((grfeopid & 0x1000) != 0)
        pbasicSet = static_cast<BASIC*>(peopid->optdat.pfnensure(pbasic, ENSK_Set));

    if ((grfeopid & 0x10) != 0)
    {
        std::byte* pbField = reinterpret_cast<std::byte*>(pbasicSet) + peopid->optdat.ibSet;

        switch (otyp)
        {
        case OTYP_Bool:
            *reinterpret_cast<BOOL*>(pbField) = prefValue->RefCoerceS32().m_n != 0;
            break;

        case OTYP_Float:
            *reinterpret_cast<float*>(pbField) = prefValue->RefCoerceF32().m_g;
            break;

        case OTYP_Vector:
            *reinterpret_cast<glm::vec3*>(pbField) = prefValue->m_vector;
            break;

        case OTYP_Vector4:
            *reinterpret_cast<glm::vec4*>(pbField) = prefValue->m_vector4;
            break;

        case OTYP_Matrix:
            *reinterpret_cast<glm::mat3*>(pbField) = glm::mat3(prefValue->m_matrix);
            break;

        case OTYP_Int:
        case OTYP_Oid:
        case OTYP_Cid:
        case OTYP_Ishd:
        case OTYP_Sfxid:
        case OTYP_Wid:
        case OTYP_Tbid:
        case OTYP_Msgid:
        case OTYP_Musid:
        case OTYP_Optid:
            *reinterpret_cast<int32_t*>(pbField) = prefValue->RefCoerceS32().m_n;
            break;

        case OTYP_Clq:
            *reinterpret_cast<CLQ*>(pbField) = prefValue->m_clq;
            break;

        case OTYP_Lm:
            *reinterpret_cast<LM*>(pbField) = prefValue->m_lm;
            break;

        case OTYP_Smp:
            *reinterpret_cast<SMP*>(pbField) = prefValue->m_smp;
            break;

        case OTYP_Smpa:
        case OTYP_Rgba:
        case OTYP_Void:
            break;

        default:
            if ((otypRaw & 0x1000U) != 0)
                *reinterpret_cast<int32_t*>(pbField) = prefValue->RefCoerceS32().m_n;
            else if ((otypRaw & 0x2000U) != 0)
                *reinterpret_cast<BASIC**>(pbField) = prefValue->m_pbasic;

            break;
        }

        return ref;
    }

    PFNRAW pfnset;

    if ((grfeopid & 0x20) != 0)
    {
        pfnset = peopid->optdat.pfnset;
    }
    else
    {
        std::byte* pvt = *reinterpret_cast<std::byte**>(pbasicSet);
        pfnset = *reinterpret_cast<PFNRAW*>(pvt + peopid->optdat.ibSet);
    }

    switch (otyp)
    {
    case OTYP_Bool:
    {
        const BOOL value = prefValue->RefCoerceS32().m_n != 0;
        reinterpret_cast<void(*)(void*, BOOL)>(pfnset)(pbasicSet, value);
        break;
    }

    case OTYP_Float:
    {
        const float value = prefValue->RefCoerceF32().m_g;
        reinterpret_cast<void(*)(void*, float)>(pfnset)(pbasicSet, value);
        break;
    }

    case OTYP_Vector:
    {
        glm::vec3 value = prefValue->m_vector;
        reinterpret_cast<void(*)(void*, glm::vec3*)>(pfnset)(pbasicSet, &value);
        break;
    }

    case OTYP_Vector4:
    {
        reinterpret_cast<void(*)(void*, glm::vec4)>(pfnset)(pbasicSet, prefValue->m_vector4);
        break;
    }

    case OTYP_Matrix:
    {
        glm::mat3 value(prefValue->m_matrix);
        reinterpret_cast<void(*)(void*, glm::mat3*)>(pfnset)(pbasicSet, &value);
        break;
    }

    case OTYP_Clq:
    {
        const glm::vec3 value(prefValue->m_clq.g0, prefValue->m_clq.g1, prefValue->m_clq.g2);
        reinterpret_cast<void(*)(void*, glm::vec3)>(pfnset)(pbasicSet, value);
        break;
    }

    case OTYP_Lm:
    {
        const glm::vec2 value(prefValue->m_lm.gMin, prefValue->m_lm.gMax);
        reinterpret_cast<void(*)(void*, glm::vec2)>(pfnset)(pbasicSet, value);
        break;
    }

    case OTYP_Smp:
    {
        const glm::vec3 value(prefValue->m_smp.svFast, prefValue->m_smp.svSlow, prefValue->m_smp.dtFast);
        reinterpret_cast<void(*)(void*, glm::vec3)>(pfnset)(pbasicSet, value);
        break;
    }

    case OTYP_Int:
    case OTYP_Oid:
    case OTYP_Cid:
    case OTYP_Ishd:
    case OTYP_Sfxid:
    case OTYP_Wid:
    case OTYP_Tbid:
    case OTYP_Msgid:
    case OTYP_Musid:
    case OTYP_Optid:
    {
        const int32_t value = prefValue->RefCoerceS32().m_n;
        reinterpret_cast<void(*)(void*, int32_t)>(pfnset)(pbasicSet, value);
        break;
    }

    case OTYP_Smpa:
    case OTYP_Rgba:
    case OTYP_Void:
        break;

    default:
    {
        if ((otypRaw & 0x1000U) != 0)
        {
            const int32_t value = prefValue->RefCoerceS32().m_n;
            reinterpret_cast<void(*)(void*, int32_t)>(pfnset)(pbasicSet, value);
        }
        else if ((otypRaw & 0x2000U) != 0)
        {
            reinterpret_cast<void(*)(void*, BASIC*)>(pfnset)(pbasicSet, prefValue->m_pbasic);
        }

        break;
    }
    }

    return ref;
}
EOPID* PeopidFind(BASIC* pbasic, int optid)
{
    if (pbasic == nullptr)
    {
        /*std::printf(
            "PeopidFind: pbasic is null, optid=%d\n",
            optid);*/

        return nullptr;
    }

    if (pbasic->pvtbasic == nullptr)
    {
        /*std::printf(
            "PeopidFind: pvtbasic is null, pbasic=%p, optid=%d\n",
            static_cast<void*>(pbasic),
            optid);*/

        return nullptr;
    }

    const CID cid = pbasic->pvtbasic->cid;
    constexpr std::size_t tableCount = std::size(g_mpcidarysplopt);

    const int cidIndex = static_cast<int>(cid);

    if (cidIndex < 0 ||
        static_cast<std::size_t>(cidIndex) >= tableCount)
    {
        std::printf(
            "PeopidFind: invalid cid=%d, tableCount=%zu, "
            "pbasic=%p, optid=%d\n",
            cidIndex,
            tableCount,
            static_cast<void*>(pbasic),
            optid);

        return nullptr;
    }

    const auto& optTable = g_mpcidarysplopt[cidIndex];

    int left = 0;
    int right = optTable.csplopt - 1;

    while (left <= right)
    {
        const int mid = left + (right - left) / 2;
        const int currentOptid = optTable.asplopt[mid].optid;

        if (currentOptid == optid)
            return optTable.asplopt[mid].peopid;

        if (optid < currentOptid)
            right = mid - 1;
        else
            left = mid + 1;
    }

    /*std::printf(
        "PeopidFind: option not found, cid=%d, "
        "pbasic=%p, optid=%d\n",
        cidIndex,
        static_cast<void*>(pbasic),
        optid);*/

    return nullptr;
}
CRef RefSetPvsFromSplice(int cref, CRef* aref, OTYP* aotyp, void** apv)
{
    CRef ret;

    for (int i = 0; i < cref; i++)
    {
        const CRef& ref = aref[i];
        OTYP otyp = aotyp[i];
        void* pv = apv[i];

        if (!pv)
            continue;

        switch (otyp)
        {
            case OTYP_Bool:
            {
                *reinterpret_cast<int*>(pv) = ref.m_bool;
                break;
            }

            case OTYP_Float:
            {
                CRef value = ref.RefCoerceF32();
                *reinterpret_cast<float*>(pv) = value.m_g;
                break;
            }

            case OTYP_Vector:
            {
                *reinterpret_cast<glm::vec3*>(pv) = ref.m_vector;
                break;
            }

            case OTYP_Matrix:
            {
                *reinterpret_cast<glm::mat4*>(pv) = ref.m_matrix;
                break;
            }

            case OTYP_Int:
            case OTYP_Oid:
            case OTYP_Cid:
            case OTYP_Ishd:
            case OTYP_Sfxid:
            case OTYP_Wid:
            case OTYP_Tbid:
            case OTYP_Msgid:
            case OTYP_Optid:
            {
                CRef value = ref.RefCoerceS32();
                *reinterpret_cast<int*>(pv) = value.m_n;
                break;
            }

            case OTYP_Clq:
            {
                *reinterpret_cast<CLQ*>(pv) = ref.m_clq;
                break;
            }

            case OTYP_Lm:
            {
                *reinterpret_cast<LM*>(pv) = ref.m_lm;
                break;
            }

            case OTYP_Smp:
            {
                *reinterpret_cast<SMP*>(pv) = ref.m_smp;
                break;
            }

            case OTYP_Rgba:
            case OTYP_Void:
            {
                break;
            }

            default:
            {
                if ((static_cast<int>(otyp) & 4096) != 0)
                {
                    CRef value = ref.RefCoerceS32();
                    *reinterpret_cast<int*>(pv) = value.m_n;
                }
                else if ((static_cast<int>(otyp) & 8192) != 0)
                {
                    *reinterpret_cast<BASIC**>(pv) = ref.m_pbasic;
                }

                break;
            }
        }
    }

    ret.SetTag(TAGK_Void);
    return ret;
}

CRef RefSetArgListFromPvs(int cargs, OTYP* aotyp, void** apv)
{
    GLS gls{};

    gls.ppairHead = nullptr;
    gls.ppairPrev = nullptr;

    for (int i = 0; i < cargs; ++i)
    {
        gls.otyp = aotyp[i];
        FAppendSpliceListElement(&gls, apv[i]);
    }

    CRef refRet;

    if (gls.ppairHead == nullptr)
        refRet.SetTag(TAGK_None);
    else
        refRet.SetPair(gls.ppairHead);

    return refRet;
}

int FAppendSpliceListElement(void* pvstate, void* pvdata)
{
    GLS* gls = static_cast<GLS*>(pvstate);
    auto pair = std::make_shared<CPair>();

    const OTYP otyp = gls->otyp;
    const uint32_t otypRaw = static_cast<uint32_t>(otyp);

    switch (otyp)
    {
    case OTYP_Bool:
    {
        pair->m_ref.SetBool(*static_cast<int*>(pvdata) != 0);
        break;
    }

    case OTYP_Float:
    {
        pair->m_ref.SetF32(*static_cast<float*>(pvdata));
        break;
    }

    case OTYP_Vector:
    {
        pair->m_ref.SetVector(*static_cast<glm::vec3*>(pvdata));
        break;
    }

    case OTYP_Vector4:
    {
        pair->m_ref.SetVector4(*static_cast<glm::vec4*>(pvdata));
        break;
    }

    case OTYP_Matrix:
    {
        pair->m_ref.SetMatrix(glm::mat4(*static_cast<glm::mat3*>(pvdata)));
        break;
    }

    case OTYP_Clq:
    {
        pair->m_ref.SetClq(*static_cast<CLQ*>(pvdata));
        break;
    }

    case OTYP_Lm:
    {
        pair->m_ref.SetLm(*static_cast<LM*>(pvdata));
        break;
    }

    case OTYP_Smp:
    {
        pair->m_ref.SetSmp(*static_cast<SMP*>(pvdata));
        break;
    }

    case OTYP_Int:
    case OTYP_Oid:
    case OTYP_Cid:
    case OTYP_Ishd:
    case OTYP_Sfxid:
    case OTYP_Wid:
    case OTYP_Tbid:
    case OTYP_Msgid:
    case OTYP_Optid:
    {
        pair->m_ref.SetS32(*static_cast<int*>(pvdata));
        break;
    }

    default:
    {
        if ((otypRaw & 0x1000U) != 0)
            pair->m_ref.SetS32(*static_cast<int*>(pvdata));
        else if ((otypRaw & 0x2000U) != 0)
        {
            BASIC* pbasicObject = *static_cast<BASIC**>(pvdata);

            pair->m_ref.SetBasic(pbasicObject);
        }
        else
            pair->m_ref.SetTag(TAGK_None);

        break;
    }
    }

    if (gls->ppairHead == nullptr)
        gls->ppairHead = pair;
    else
        gls->ppairPrev->m_ppairNext = pair;

    gls->ppairPrev = pair;

    return 1;
}

int FSpliceListElementExists(void* pvstate, void* pvdata)
{
    GLS* gls = static_cast<GLS*>(pvstate);

    if (!gls->ppairHead)
        return 0;

    CRef ref;
    uint32_t otyp = static_cast<uint32_t>(gls->otyp);

    switch (otyp)
    {
        case 0:
        ref.SetBool(*static_cast<int*>(pvdata));
        break;

        case 1:
        ref.SetF32(*static_cast<float*>(pvdata));
        break;

        case 5:
        case 6:
        case 7:
        case 8:
        case 14:
        case 15:
        case 16:
        case 17:
        ref.SetS32(*static_cast<int*>(pvdata));
        break;

        default:
        if ((otyp & 0x1000) != 0)
            ref.SetS32(*static_cast<int*>(pvdata));
        else if ((otyp & 0x2000) != 0)
            ref.SetBasic(*static_cast<BASIC**>(pvdata));
        else
            return 0;
        break;
    }

    for (std::shared_ptr<CPair> pair = gls->ppairHead; pair; pair = pair->m_ppairNext)
    {
        if (pair->m_ref == ref)
            return 1;
    }

    return 0;
}

SPLOPT g_asploptBasic[2] =
{
    { 0x1, &g_aeopid[0] }, // [000]
    { 0x2, &g_aeopid[1] }, // [001]
};

